{
  "vulnerable_symbols": [
    "yaml.full_load",
    "yaml.load"
  ],
  "trigger": "应用使用 PyYAML <5.3.1 的 full_load 或 FullLoader 解析攻击者可控 YAML，其中包含 !!python/object/new 构造器。",
  "preconditions": [
    "PyYAML 版本低于 5.3.1",
    "yaml.load 使用 FullLoader（或调用 full_load）"
  ],
  "exploit_evidence": [
    {
      "src": 1,
      "kind": "poc",
      "quote": "data=load(content,Loader=FullLoader)# Using vulnerable FullLoader"
    }
  ],
  "fixed_version": "5.3.1",
  "summary_zh": "PyYAML 5.3 的 FullLoader 解析不可信 YAML 可致 RCE，升级 5.3.1。"
}
